	@Test
	void preservesDuplicateRowsBeforeOffset() {
		String query = "SELECT DISTINCT ?x WHERE { { SELECT ?x WHERE { VALUES ?x { 1 1 } } OFFSET 1 } }";
		assertEquals(List.of("1"), values(evaluate(query, false), "x"));
		assertEquals(List.of("1"), values(evaluate(query, true), "x"));
	}

	@Test
	void preservesOffsetInsideAsk() {
		String query = "ASK { { SELECT ?x WHERE { VALUES ?x { 1 1 } } OFFSET 1 } }";
		assertFalse(evaluate(query, false).isEmpty());
		assertFalse(evaluate(query, true).isEmpty());
	}

	@Test
	void restoresSetContextForSiblingAfterSlice() {
		String query = """
				SELECT DISTINCT ?x ?y WHERE {
				  { SELECT ?x WHERE { VALUES ?x { 1 1 } } OFFSET 1 }
				  VALUES ?y { 2 2 }
				}
				""";
		assertEquals(evaluate(query, false), evaluate(query, true));
		QueryRoot root = new QueryRoot(new SPARQLParser().parseQuery(query, "urn:test:").getTupleExpr());
		new LmdbSetSemanticsOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment assignment) {
				int rows = 0;
				for (BindingSet ignored : assignment.getBindingSets()) {
					rows++;
				}
				assertEquals(assignment.getBindingNames().contains("x") ? 2 : 1, rows);
			}
		});
	}

